const panier: any[] = [];
function ajouter(nom, prix) {
  panier.push([nom, prix]);
}
function total() {
  return 0;
}

solution:
const panier: [string, number][] = [];

function ajouter(nom: string, prix: number): void {
  panier.push([nom, prix]);
}

function total(): number {
  return panier.reduce((s, [, prix]) => s + prix, 0);
}
